#include "mesh/cubed_sphere/composite_checkpoint.hpp"
#include "z4c/hyperboloidal/composite_evolution.hpp"
namespace h=z4c::hyperboloidal;namespace c=cubed_sphere;using V=std::vector<Real>;using Rate=h::MetricRate<Real>;using U=h::Z4cJet<Real>;
constexpr int ti[6]={0,0,0,1,1,2},tj[6]={0,1,2,1,2,2};
struct Audit {
 h::CompositeTensorEvolution e;const c::CompositeDifference &g;size_t N,S;V padded;std::vector<U> surface;std::map<std::string,V> body,edge;V hc,hs,ht,bc,bs,bt,alphapad,apad,bgradpad;Real metric_rate_identity=0;bool resolved=false;
 Audit(const c::CompositeSnapshot&s,bool resolve=false):e(s.mesh,s.telegraph,s.tolerance,s.spatial_order,true,s.wormhole_chart,s.isotropic_reference,s.scri_radial_points,s.radial_interface_stencils,s.positive_storage,s.telegraph_width,s.enriched_log_derivatives,s.radial_line_smoothing,s.topology_coarsening,s.log_halo_enrichment,s.log_halo_radius,s.puncture_derivative_scheme,s.boundary_derivative_scheme,resolve?false:s.affine_shift_derivatives),g(e.shift.grid),N(g.active.size()),S(e.scri->rows.size()){
  if(N>50000||!s.affine_shift_derivatives||s.positive_storage!=2||s.log_halo_enrichment)throw std::runtime_error("audit matched-affine/log/nohalo support");e.state=s.fields;e.beta_delta=s.shift_warm_start;e.scri->values=s.boundary_fields;padded=e.Padded(e.state);e.GeometryJets(e.state,padded);if(resolve){e.SolveShift(padded);resolved=true;}else Install();e.BoundaryRates(padded,s.dt);SurfaceJets();BuildRates();
 }
 void Install(){const auto boundary=e.Boundary(padded);e.shift_affine.emplace(e.shift.affine_derivative->Fit(e.beta_delta));e.beta_padded=e.shift.affine_derivative->PaddedRemainder(e.beta_delta,*e.shift_affine,boundary);for(size_t p=0;p<S;++p){const auto&x=e.scri->rows[p].geometry.x;const auto q=boundary({x[0],x[1],x[2]});for(int v=0;v<3;++v)e.scri->beta[3*p+v]=q[v];}for(size_t p=0;p<N;++p){const auto q=e.shift.affine_derivative->Sample(e.beta_delta,e.beta_padded,*e.shift_affine,p);for(int v=0;v<3;++v){e.jets[p].beta.value[v]+=q.value[v];for(int a=0;a<3;++a){e.jets[p].beta.d[a][v]+=q.d[a][v];for(int b=0;b<3;++b)e.jets[p].beta.dd[a][b][v]+=q.dd[a][b][v];}}}}
 void SurfaceJets(){surface.resize(S);c::HermiteBoundarySampler sampler(*e.scri);V remainder=e.scri->beta;if(e.shift_affine)for(size_t p=0;p<S;++p){auto a=e.shift.affine_derivative->At(*e.shift_affine,e.scri->rows[p].geometry.x);for(int v=0;v<3;++v)remainder[3*p+v]-=a.value[v];}auto field=sampler.Prepare(padded,e.scri->values,22,1),beta=sampler.Prepare(e.beta_padded,remainder,3,1);for(size_t p=0;p<S;++p){const auto &x=e.scri->rows[p].geometry.x;auto q=sampler.Sample(p,field),b=sampler.Sample(p,beta);h::VectorJet<Real> a{};if(e.shift_affine)a=e.shift.affine_derivative->At(*e.shift_affine,x);surface[p]=h::UnpackComposite(x,q.value,q.d,q.dd,true,0,2);for(int v=0;v<3;++v){surface[p].beta.value[v]+=e.scri->beta[3*p+v];for(int d=0;d<3;++d){surface[p].beta.d[d][v]+=b.d[v][d]+a.d[d][v];for(int j=0;j<3;++j)surface[p].beta.dd[d][j][v]+=b.dd[v][d][j];}}}}
 V Pad(const V&active,const V&boundary,int components){if(active.size()!=N*components||boundary.size()!=S*components)throw std::runtime_error("rate pad layout");V out(components*g.count,0);for(size_t p=0;p<N;++p)for(int f=0;f<components;++f)out[f*g.count+g.active[p]]=active[p*components+f];std::map<std::array<Real,3>,V>cache;g.Fill(out,components,[&](int f,const auto&x){auto it=cache.find(x);if(it==cache.end())it=cache.emplace(x,e.scri->Interpolate(boundary,components,x.data())).first;return it->second[f];});return out;}
 void BuildRates(){hc.resize(6*N);hs.resize(6*N);ht.resize(6*N);bc.resize(6*S);bs.resize(6*S);bt.resize(6*S);V alpha(N),alphaB(S),A(6*N),AB(6*S),grad(9*N),gradB(9*S);
  for(size_t p=0;p<N+S;++p){bool boundary=p>=N;const size_t k=boundary?p-N:p;const auto&u=boundary?surface[k]:e.jets[k];const Real*x=boundary?e.scri->rows[k].geometry.x:g.geometry[k].x;const auto r=h::ConformalRHS(u,h::CompositeOmegaAt(x,u,boundary),Real(4),Real(-.99),true);const auto shift=h::ShiftMetricRate(u.metric,u.beta);auto &C=boundary?bc:hc;auto &H=boundary?bs:hs;auto &T=boundary?bt:ht;auto &a=boundary?alphaB:alpha;auto &aa=boundary?AB:A;auto &d=boundary?gradB:grad;a[k]=u.alpha.value;for(int v=0;v<3;++v)for(int j=0;j<3;++j)d[k*9+3*v+j]=u.beta.d[j][v];for(int t=0;t<6;++t){const int i=ti[t],j=tj[t];C[6*k+t]=-2*u.alpha.value*u.a.k[i][j];T[6*k+t]=boundary?e.boundary_rhs[22*k+1+t]:r.regular.metric[i][j];H[6*k+t]=T[6*k+t]-C[6*k+t];aa[6*k+t]=u.a.k[i][j];metric_rate_identity=std::max(metric_rate_identity,std::abs(T[6*k+t]-C[6*k+t]-shift.h[i][j]));}}
  alphapad=Pad(alpha,alphaB,1);apad=Pad(A,AB,6);bgradpad=Pad(grad,gradB,9);
 }
 void Set(std::map<std::string,V>&data,const std::string&name,size_t p,const Real*v,size_t size){auto &out=data[name];if(out.empty())out.resize(3*size);for(int i=0;i<3;++i)out[3*p+i]=v[i];}
 void Evaluate(){const auto C=Pad(hc,bc,6),H=Pad(hs,bs,6),T=Pad(ht,bt,6);c::HermiteBoundarySampler sampler(*e.scri);auto cp=sampler.Prepare(C,bc,6,1),hp=sampler.Prepare(H,bs,6,1),tp=sampler.Prepare(T,bt,6,1);V alphaB(S),AB(6*S),gradB(9*S);for(size_t p=0;p<S;++p){alphaB[p]=surface[p].alpha.value;for(int t=0;t<6;++t)AB[6*p+t]=surface[p].a.k[ti[t]][tj[t]];for(int v=0;v<3;++v)for(int a=0;a<3;++a)gradB[9*p+3*v+a]=surface[p].beta.d[a][v];}auto ap=sampler.Prepare(alphapad,alphaB,1,1),aa=sampler.Prepare(apad,AB,6,1),bg=sampler.Prepare(bgradpad,gradB,9,1);
  for(size_t p=0;p<N+S;++p){const bool boundary=p>=N;const size_t k=boundary?p-N:p;const auto &u=boundary?surface[k]:e.jets[k];const auto geo=h::Geometry(u.metric);Rate directC{},actualC{},actualH{},actualT{},product{},alpha_chain{},A_chain{},beta2{};auto directH=h::ShiftMetricRate(u.metric,u.beta);auto composed=u.beta;Real dalpha[3]{},dA[6][3]{};c::ScriSurface::Jets cs,hh,tt,as,aas,gs;if(boundary){cs=sampler.Sample(k,cp);hh=sampler.Sample(k,hp);tt=sampler.Sample(k,tp);as=sampler.Sample(k,ap);aas=sampler.Sample(k,aa);gs=sampler.Sample(k,bg);}else{Real dd[3][3];g.Derivatives(alphapad,0,k,dalpha,dd);for(int t=0;t<6;++t)g.Derivatives(apad,t,k,dA[t],dd);}for(int t=0;t<6;++t){const int i=ti[t],j=tj[t];const size_t off=6*k+t;actualC.h[i][j]=actualC.h[j][i]=(boundary?bc:hc)[off];actualH.h[i][j]=actualH.h[j][i]=(boundary?bs:hs)[off];actualT.h[i][j]=actualT.h[j][i]=(boundary?bt:ht)[off];directC.h[i][j]=directC.h[j][i]=-2*u.alpha.value*u.a.k[i][j];Real dc[3]{},dh[3]{},dt[3]{},dd[3][3];if(boundary){for(int a=0;a<3;++a){dc[a]=cs.d[t][a];dh[a]=hh.d[t][a];dt[a]=tt.d[t][a];dalpha[a]=as.d[0][a];dA[t][a]=aas.d[t][a];}}else{g.Derivatives(C,t,k,dc,dd);g.Derivatives(H,t,k,dh,dd);g.Derivatives(T,t,k,dt,dd);}for(int a=0;a<3;++a){directC.dh[a][i][j]=directC.dh[a][j][i]=-2*(u.alpha.d[a]*u.a.k[i][j]+u.alpha.value*u.a.dk[a][i][j]);actualC.dh[a][i][j]=actualC.dh[a][j][i]=dc[a];actualH.dh[a][i][j]=actualH.dh[a][j][i]=dh[a];actualT.dh[a][i][j]=actualT.dh[a][j][i]=dt[a];product.dh[a][i][j]=product.dh[a][j][i]=dc[a]+2*(dalpha[a]*u.a.k[i][j]+u.alpha.value*dA[t][a]);alpha_chain.dh[a][i][j]=alpha_chain.dh[a][j][i]=-2*(dalpha[a]-u.alpha.d[a])*u.a.k[i][j];A_chain.dh[a][i][j]=A_chain.dh[a][j][i]=-2*u.alpha.value*(dA[t][a]-u.a.dk[a][i][j]);}}
   for(int v=0;v<3;++v)for(int a=0;a<3;++a){Real d[3],dd[3][3];if(boundary)for(int b=0;b<3;++b)d[b]=gs.d[3*v+a][b];else g.Derivatives(bgradpad,3*v+a,k,d,dd);for(int b=0;b<3;++b)composed.dd[b][a][v]=d[b];}const auto composedH=h::ShiftMetricRate(u.metric,composed);for(int d=0;d<3;++d)for(int i=0;i<3;++i)for(int j=0;j<3;++j)beta2.dh[d][i][j]=composedH.dh[d][i][j]-directH.dh[d][i][j];
   Real exp[3],L[3],src[3],discrete[3],prod[3],chain[3],achain[3],ddiff[3],cvar[3],hvar[3];h::ApplyEllipticShift(u.metric,geo,u.beta,L);h::EllipticShiftSource(u,geo,Real(0),src);for(int i=0;i<3;++i)exp[i]=L[i]-src[i];h::MetricConnectionVariation(u.metric,geo,actualT,discrete);h::MetricConnectionVariation(u.metric,geo,product,prod);h::MetricConnectionVariation(u.metric,geo,alpha_chain,chain);h::MetricConnectionVariation(u.metric,geo,A_chain,achain);h::MetricConnectionVariation(u.metric,geo,beta2,ddiff);Rate cdef{},hdef{};for(int d=0;d<3;++d)for(int i=0;i<3;++i)for(int j=0;j<3;++j){cdef.dh[d][i][j]=actualC.dh[d][i][j]-directC.dh[d][i][j];hdef.dh[d][i][j]=actualH.dh[d][i][j]-directH.dh[d][i][j];}h::MetricConnectionVariation(u.metric,geo,cdef,cvar);h::MetricConnectionVariation(u.metric,geo,hdef,hvar);auto &data=boundary?edge:body;const size_t size=boundary?S:N;Set(data,"expanded_original",k,exp,size);Set(data,"metric_built_V",k,geo.contracted,size);Set(data,"independent_Lambda",k,u.lambda.value,size);Set(data,"actual_discrete",k,discrete,size);Set(data,"product_leibniz",k,prod,size);Set(data,"physical_alpha_chart_difference",k,chain,size);Set(data,"A_jet_difference",k,achain,size);Set(data,"curvature_product_total",k,cvar,size);Set(data,"shift_composition_total",k,hvar,size);Set(data,"beta_D2_vs_D1composition",k,ddiff,size);Real residual[3],rest[3],closure[3];for(int i=0;i<3;++i){residual[i]=discrete[i]-exp[i];rest[i]=hvar[i]-ddiff[i];closure[i]=residual[i]-cvar[i]-hvar[i];}Set(data,"discrete_minus_expanded",k,residual,size);Set(data,"shift_metric_products_and_halos",k,rest,size);Set(data,"decomposition_closure",k,closure,size);
  }
 }
 std::pair<V,V> MetricV(const V&state,const V&boundary){const auto backup=e.scri->values;e.scri->values=boundary;const V pad=e.Padded(state);e.scri->values=backup;V bulk(3*N),surfaceV(3*S);for(size_t p=0;p<N;++p){h::MetricJet<Real>metric{};for(int t=0;t<6;++t){int i=ti[t],j=tj[t];metric.g[i][j]=metric.g[j][i]=state[22*p+1+t]+(i==j?1:0);Real d[3],dd[3][3];g.Derivatives(pad,1+t,p,d,dd);for(int a=0;a<3;++a)metric.dg[a][i][j]=metric.dg[a][j][i]=d[a];}const auto geo=h::Geometry(metric);if(!geo.valid)throw std::runtime_error("finite epsilon metric lost SPD");for(int i=0;i<3;++i)bulk[3*p+i]=geo.contracted[i];}c::HermiteBoundarySampler sampler(*e.scri);auto prepared=sampler.Prepare(pad,boundary,22,1);for(size_t p=0;p<S;++p){auto sampled=sampler.Sample(p,prepared);const auto &x=e.scri->rows[p].geometry.x;const auto u=h::UnpackComposite(x,sampled.value,sampled.d,sampled.dd,true,0,2);const auto geo=h::Geometry(u.metric);if(!geo.valid)throw std::runtime_error("finite epsilon surface metric lost SPD");for(int i=0;i<3;++i)surfaceV[3*p+i]=geo.contracted[i];}return {bulk,surfaceV};}
 void Finite(){for(Real epsilon:{1e-4,1e-5,1e-6,1e-7}){V plus=e.state,minus=e.state,bplus=e.scri->values,bminus=bplus;for(size_t p=0;p<N;++p)for(int t=0;t<6;++t){plus[22*p+1+t]+=epsilon*ht[6*p+t];minus[22*p+1+t]-=epsilon*ht[6*p+t];}for(size_t p=0;p<S;++p)for(int t=0;t<6;++t){bplus[22*p+1+t]+=epsilon*bt[6*p+t];bminus[22*p+1+t]-=epsilon*bt[6*p+t];}auto P=MetricV(plus,bplus),M=MetricV(minus,bminus);std::ostringstream name;name<<"finite_epsilon_"<<epsilon;for(int which=0;which<2;++which){auto &data=which?edge:body;const auto &a=which?P.second:P.first,&b=which?M.second:M.first;V value(a.size()),error(a.size());for(size_t i=0;i<a.size();++i){value[i]=(a[i]-b[i])/(2*epsilon);error[i]=value[i]-data.at("actual_discrete")[i];}data[name.str()]=value;data[name.str()+"_error"]=error;}}}
 void Write(const std::string&path){for(int which=0;which<2;++which){const auto&data=which?edge:body;std::ofstream out(path+(which?".surface.csv":".bulk.csv"));out<<std::setprecision(17)<<"point,x,y,z,r,weight,conformal_weight,chi,alpha";for(const auto&[name,values]:data)for(int v=0;v<3;++v)out<<','<<name<<'_'<<v;out<<'\n';for(size_t p=0;p<(which?S:N);++p){const Real*x=which?e.scri->rows[p].geometry.x:g.geometry[p].x;Real r=0;for(int i=0;i<3;++i)r+=x[i]*x[i];Real w=which?1:e.shift.norm_volume[p];out<<p<<','<<x[0]<<','<<x[1]<<','<<x[2]<<','<<std::sqrt(r)<<','<<w<<','<<(which?1:e.shift.conformal_volume[p])<<','<<(which?surface[p]:e.jets[p]).chi.value<<','<<(which?surface[p]:e.jets[p]).alpha.value;for(const auto&[name,values]:data)for(int v=0;v<3;++v)out<<','<<values[3*p+v];out<<'\n';}}}
 void Summary(){std::cout<<std::setprecision(17)<<"{\"cells\":"<<N<<",\"surface_points\":"<<S<<",\"recomputed_scri_pole\":"<<e.boundary_pole<<",\"affine_shift\":"<<(e.affine_shift_derivatives?"true":"false")<<",\"fresh_old_operator_solve\":"<<(resolved?"true":"false")<<",\"metric_rate_value_identity_max\":"<<metric_rate_identity<<",\"body\":{";bool first=true;for(const auto&[name,v]:body){if(!first)std::cout<<',';first=false;Real maximum=0,conformal=0,volume=0;for(size_t p=0;p<N;++p){volume+=e.shift.conformal_volume[p];for(int d=0;d<3;++d){maximum=std::max(maximum,std::abs(v[3*p+d]));conformal+=e.shift.conformal_volume[p]*v[3*p+d]*v[3*p+d];}}std::cout<<'"'<<name<<"\":{\"physical_rms\":"<<std::sqrt(e.shift.Dot(v,v))<<",\"conformal_rms\":"<<std::sqrt(conformal/volume)<<",\"point_max\":"<<maximum<<'}';}std::cout<<"},\"surface\":{";first=true;for(const auto&[name,v]:edge){if(!first)std::cout<<',';first=false;Real maximum=0,rms=0;for(Real x:v){maximum=std::max(maximum,std::abs(x));rms+=x*x;}std::cout<<'"'<<name<<"\":{\"point_rms\":"<<std::sqrt(rms/S)<<",\"point_max\":"<<maximum<<'}';}std::cout<<"},\"no_evolution\":true,\"operator_adopted\":false}\n";}
};
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=4&&argc!=5)throw std::runtime_error("accepted_snapshot tag output_prefix [old_operator_resolve]");auto snapshot=c::CompositeCheckpoint::Read(argv[1],argv[2]);if(snapshot.step!=2)throw std::runtime_error("expected acceptedstep2");bool resolve=argc==5;if(resolve&&std::string(argv[4])!="old_operator_resolve")throw std::runtime_error("unsupported audit mode");Audit audit(snapshot,resolve);audit.Evaluate();audit.Finite();audit.Write(argv[3]);audit.Summary();}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
